import base64
import os
from typing import Optional

import requests


AZURE_VISION_ENDPOINT_ENV = "AZURE_VISION_ENDPOINT"
AZURE_VISION_KEY_ENV = "AZURE_VISION_KEY"
AZURE_VISION_API_VERSION = "2023-02-01-preview"


def _load_image_bytes(image_input: str) -> bytes:
    if image_input.startswith(("http://", "https://")):
        resp = requests.get(image_input, timeout=30)
        resp.raise_for_status()
        return resp.content

    if os.path.isfile(image_input):
        with open(image_input, "rb") as f:
            return f.read()

    try:
        return base64.b64decode(image_input, validate=True)
    except Exception as exc:
        raise ValueError(
            "image_input must be a URL, a file path, or a base64-encoded image string"
        ) from exc


def generate_visual_description(image_input: str, max_words: int = 20) -> str:
    endpoint = os.environ.get(AZURE_VISION_ENDPOINT_ENV)
    key = os.environ.get(AZURE_VISION_KEY_ENV)
    if not endpoint or not key:
        raise EnvironmentError(
            f"Missing required Azure Vision environment variables: {AZURE_VISION_ENDPOINT_ENV}, {AZURE_VISION_KEY_ENV}"
        )

    image_bytes = _load_image_bytes(image_input)

    url = (
        endpoint.rstrip("/")
        + "/computervision/imageanalysis:analyze"
        + f"?api-version={AZURE_VISION_API_VERSION}&features=caption&language=en&gender-neutral-caption=true"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/octet-stream",
    }

    response = requests.post(url, headers=headers, data=image_bytes, timeout=60)
    response.raise_for_status()
    data = response.json()

    caption = (
        data.get("captionResult", {}).get("text")
        or data.get("description", {}).get("captions", [{}])[0].get("text")
        or ""
    ).strip()

    if not caption:
        return "No caption available."

    words = caption.split()
    if len(words) > max_words:
        caption = " ".join(words[:max_words]).rstrip(",.;:") + "..."

    return caption
